#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	// UPROPERTY so the GC cannot collect it while the GameMode is alive.
	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker = nullptr;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "UArenaScoreTracker::AddPoints() dereferenced a dangling pointer: AArenaGameMode::ScoreTracker was a plain C++ pointer (UArenaScoreTracker*) without UPROPERTY, so the Unreal garbage collector could collect the UArenaScoreTracker object created with NewObject in BeginPlay. The log shows 'LogGarbage: Collecting garbage: 412 objects purged' at 21:05:13, and 14 s later the first goal at 21:05:27 crashed with EXCEPTION_ACCESS_VIOLATION reading 0xffffffffffffffff in AddPoints() (ArenaScoreTracker.cpp:18). Fixed by making ScoreTracker a UPROPERTY TObjectPtr in ArenaGameMode.h.",
  "no_colors_cause": "The palette asset /Game/Data/Palettes/DA_Primary was not cooked into the packaged build: DefaultGame.ini had bCookAll=False and DirectoriesToAlwaysCook listed only /Game/Data/Effects, so the Palettes directory was omitted from the pak. At runtime LoadObject failed ('Couldn't find file for package /Game/Data/Palettes/DA_Primary') and the game fell back to gray ('Palette is null, using fallback gray'). Fixed by adding /Game/Data/Palettes to DirectoriesToAlwaysCook in Config/DefaultGame.ini."
}
